import{_ as t,o as r,c as o,ah as n}from"./chunks/framework.C-FRNfAJ.js";const v=JSON.parse('{"title":"Certificat et Canopé","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apprenant/certification.md","filePath":"src/guide/apprenant/certification.md"}'),s={name:"guide/apprenant/certification.md"};function a(i,e,l,d,u,c){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="certificat-et-canope" tabindex="-1">Certificat et Canopé <a class="header-anchor" href="#certificat-et-canope" aria-label="Permalink to &quot;Certificat et Canopé&quot;">​</a></h1><h2 id="les-quatre-conditions" tabindex="-1">Les quatre conditions <a class="header-anchor" href="#les-quatre-conditions" aria-label="Permalink to &quot;Les quatre conditions&quot;">​</a></h2><p>Le <strong>certificat NextBoxx</strong> est délivré quand <strong>les quatre conditions</strong> sont réunies. Aucune ne compense une autre :</p><ol><li>votre <strong>moyenne</strong> est d&#39;au moins 10/20 ;</li><li><strong>aucun bloc</strong> n&#39;est sous 8/20 ;</li><li>votre <strong>soutenance</strong> est validée par le jury ;</li><li>le <strong>solde</strong> de la formation est intégralement payé.</li></ol><p>La page de résultats de la cohorte montre au Coordinateur, pour chaque apprenant, laquelle manque. Si vous êtes bloqué, c&#39;est lui qu&#39;il faut contacter.</p><h2 id="la-delivrance" tabindex="-1">La délivrance <a class="header-anchor" href="#la-delivrance" aria-label="Permalink to &quot;La délivrance&quot;">​</a></h2><p>Le Coordinateur pédagogique délivre le certificat, <strong>une seule fois</strong>, au nom du président du jury. Le document est un PDF <strong>scellé</strong>, qui ne peut plus être modifié.</p><p>Il porte une <strong>mention</strong> sur l&#39;échelle française :</p><table tabindex="0"><thead><tr><th>Mention</th><th>À partir de</th></tr></thead><tbody><tr><td>Passable</td><td>10/20</td></tr><tr><td>Assez bien</td><td>12/20</td></tr><tr><td>Bien</td><td>14/20</td></tr><tr><td>Très bien</td><td>16/20</td></tr></tbody></table><p>Ces seuils sont ceux par défaut ; l&#39;Administrateur peut les régler.</p><p>Vous recevez en même temps un <strong>relevé de compétences</strong>, qui détaille les notes par bloc et les rattrapages, le projet tutoré, le stage et son entreprise, et la moyenne. Il n&#39;a pas de valeur seul. Certificat (<code>CERT-NB-AAAA-XXX</code>) et relevé (<code>REL-NB-AAAA-XXX</code>) sont dans <strong>Mon inscription</strong> et <strong>Mes documents</strong>.</p><h2 id="devenir-canope" tabindex="-1">Devenir Canopé <a class="header-anchor" href="#devenir-canope" aria-label="Permalink to &quot;Devenir Canopé&quot;">​</a></h2><p>La délivrance du certificat marque la fin de votre inscription et ouvre le <strong>Parcours Canopé</strong> :</p><ul><li>votre inscription passe à « Terminée » ;</li><li>vous sortez du cours de votre cohorte dans Sève, car l&#39;accès aux cours actifs est retiré ;</li><li>votre compte passe à l&#39;état <strong>Canopé</strong>, que Sève reflète : vous gardez l&#39;accès à la <strong>communauté</strong>, au <strong>mentorat</strong> et au <strong>portfolio</strong>, sans limite de durée.</li></ul><p>Tant que vous êtes Canopé, vous pouvez par ailleurs demander à devenir Coach-Tuteur (voir <a href="./../premiers-pas.html#demander-un-role">Demander un rôle</a>) ou candidater à <strong>L&#39;Éclosion</strong>, le programme d&#39;incubation de NextBoxx, depuis <strong>Activités → Mon projet L&#39;Éclosion</strong>.</p><h2 id="etre-visible-des-entreprises" tabindex="-1">Être visible des entreprises <a class="header-anchor" href="#etre-visible-des-entreprises" aria-label="Permalink to &quot;Être visible des entreprises&quot;">​</a></h2><p>Une fois certifié, vous pouvez vous rendre visible des entreprises qui recrutent. C&#39;est <strong>votre choix</strong>, et il se défait à tout moment. Dans <strong>Paramètres → Profil entreprises</strong> :</p><ol><li>rédigez une courte <strong>présentation</strong> de ce que vous cherchez et de ce que vous apportez ;</li><li>ajoutez votre <strong>CV</strong> (PDF, 5 Mo au plus), obligatoire pour être visible ;</li><li>cochez <strong>Être visible des entreprises</strong>.</li></ol><p>Une entreprise voit d&#39;abord votre prénom et l&#39;initiale de votre nom, vos certificats et votre présentation. Vos coordonnées et votre CV ne lui sont communiqués que si elle retient votre profil. Si vous masquez votre profil, il quitte les propositions en attente ; celles déjà retenues restent partagées.</p><h2 id="si-vous-abandonnez" tabindex="-1">Si vous abandonnez <a class="header-anchor" href="#si-vous-abandonnez" aria-label="Permalink to &quot;Si vous abandonnez&quot;">​</a></h2><p>Un abandon, qu&#39;il soit volontaire ou enregistré pour impayé après J+30, met fin à votre inscription. <strong>Il n&#39;y a jamais de certificat partiel.</strong></p><p>Si vous avez validé <strong>au moins un bloc</strong>, le Coordinateur peut vous délivrer une <strong>attestation partielle</strong>. Elle liste les blocs validés, ceux qui ne l&#39;ont pas été ou n&#39;ont pas été suivis, et le motif de l&#39;interruption. Elle s&#39;accompagne du relevé de compétences.</p><h2 id="combien-de-temps-vos-documents-sont-conserves" tabindex="-1">Combien de temps vos documents sont conservés <a class="header-anchor" href="#combien-de-temps-vos-documents-sont-conserves" aria-label="Permalink to &quot;Combien de temps vos documents sont conservés&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Durée</th></tr></thead><tbody><tr><td>Certificats, attestations partielles</td><td>Sans limite</td></tr><tr><td>Conventions, factures, avoirs</td><td>10 ans</td></tr><tr><td>Candidature refusée</td><td>12 mois, puis anonymisation</td></tr><tr><td>Compte inactif</td><td>Désactivé après un an sans connexion, données conservées</td></tr></tbody></table>',24)])])}const m=t(s,[["render",a]]);export{v as __pageData,m as default};
